import{_ as i,o as a,c as t,a2 as r}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"课前准备清单","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/prep-checklist.md","filePath":"appendix/prep-checklist.md"}'),e={name:"appendix/prep-checklist.md"};function o(n,l,s,h,u,p){return a(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="课前准备清单" tabindex="-1">课前准备清单 <a class="header-anchor" href="#课前准备清单" aria-label="Permalink to &quot;课前准备清单&quot;">​</a></h1><blockquote><p>📌 在开始学习之前，请确保你已经准备好以下内容。</p></blockquote><hr><h2 id="一、账号准备" tabindex="-1">一、账号准备 <a class="header-anchor" href="#一、账号准备" aria-label="Permalink to &quot;一、账号准备&quot;">​</a></h2><ul><li><p>[ ] <strong>ChatGPT 账号</strong></p><ul><li>注册地址：<a href="https://chatgpt.com" target="_blank" rel="noreferrer">https://chatgpt.com</a></li><li>推荐版本：Plus（$20/月）或 Pro（$200/月）</li><li>免费版也可以体验，但额度有限</li></ul></li><li><p>[ ] <strong>邮箱验证</strong></p><ul><li>确保你的注册邮箱已完成验证</li><li>检查垃圾邮件文件夹，确认验证邮件已收到</li></ul></li></ul><hr><h2 id="二、设备准备" tabindex="-1">二、设备准备 <a class="header-anchor" href="#二、设备准备" aria-label="Permalink to &quot;二、设备准备&quot;">​</a></h2><ul><li><p>[ ] <strong>电脑操作系统</strong></p><ul><li>macOS 用户：macOS 12.0 及以上</li><li>Windows 用户：Windows 10 及以上</li><li>Chromebook 用户：支持 Chrome OS 即可</li></ul></li><li><p>[ ] <strong>浏览器</strong></p><ul><li>推荐使用最新版 Chrome、Edge 或 Firefox</li><li>确保浏览器已更新到最新版本</li></ul></li><li><p>[ ] <strong>存储空间</strong></p><ul><li>至少预留 500MB 可用空间用于安装和缓存</li></ul></li></ul><hr><h2 id="三、网络环境" tabindex="-1">三、网络环境 <a class="header-anchor" href="#三、网络环境" aria-label="Permalink to &quot;三、网络环境&quot;">​</a></h2><ul><li>[ ] <strong>稳定的网络连接</strong><ul><li>建议宽带速度 50Mbps 以上</li><li>如果使用 WiFi，确保信号强度良好</li><li>避免在公共 WiFi 环境下使用（可能影响连接稳定性）</li></ul></li></ul><hr><h2 id="四、练习材料" tabindex="-1">四、练习材料 <a class="header-anchor" href="#四、练习材料" aria-label="Permalink to &quot;四、练习材料&quot;">​</a></h2><ul><li><p>[ ] <strong>一个待整理的文件夹</strong></p><ul><li>在桌面创建一个名为&quot;Codex 练习&quot;的文件夹</li><li>在里面放入一些不同类型的文件用于练习： <ul><li>2-3 个文本文件（.txt）</li><li>2-3 个图片文件（.jpg 或 .png）</li><li>1-2 个 PDF 文件</li><li>1 个 Excel 文件（.xlsx）</li></ul></li></ul></li><li><p>[ ] <strong>一个笔记本</strong></p><ul><li>记录你在学习过程中遇到的问题和解决方案</li><li>记录你觉得有用的指令模板</li></ul></li></ul><hr><h2 id="五、心理准备" tabindex="-1">五、心理准备 <a class="header-anchor" href="#五、心理准备" aria-label="Permalink to &quot;五、心理准备&quot;">​</a></h2><ul><li>[ ] <strong>保持好奇心</strong> — 多尝试不同的指令，看看 Codex 能做什么</li><li>[ ] <strong>不怕犯错</strong> — 出错是学习的一部分，学会修正比不犯错更重要</li><li>[ ] <strong>循序渐进</strong> — 不要急于求成，每个模块都要动手实操</li></ul><hr><h2 id="六、安全检查" tabindex="-1">六、安全检查 <a class="header-anchor" href="#六、安全检查" aria-label="Permalink to &quot;六、安全检查&quot;">​</a></h2><ul><li>[ ] <strong>备份重要文件</strong> — 在让 Codex 操作重要文件前，先做好备份</li><li>[ ] <strong>设置合适的权限</strong> — 初学者建议使用&quot;默认权限&quot;模式</li><li>[ ] <strong>不输入敏感信息</strong> — 密码、银行卡号等永远不要输入给 AI</li></ul><hr><h2 id="七、准备完成" tabindex="-1">七、准备完成 <a class="header-anchor" href="#七、准备完成" aria-label="Permalink to &quot;七、准备完成&quot;">​</a></h2><p>当你勾选了以上所有项目后，就可以开始学习第一课了！</p><p>👉 <a href="./../modules/module-1/lesson-1.html">第 1 课：AI 编程助手是什么？</a></p>',24)])])}const g=i(e,[["render",o]]);export{c as __pageData,g as default};
